#' Example 1.3.2: expected mean squares in the fixed and the mixed model
#'
#' @description
#' Drugs are given to whole herds and doses to animals within herds (\code{\link{ex124}}). With herd random, drug is
#' tested against herd within drug (Table 1.3.2.2); with one observation deleted the two expected mean squares no
#' longer match (Table 1.3.2.3: 9.7143 and 9.7222), so the F test is only approximate.
#'
#' @references
#' Duchateau, L., Janssen, P. and Rowlands, G. J. (1998). \emph{Linear Mixed Models. An Introduction with
#' Applications in Veterinary Research}. International Livestock Research Institute, Nairobi.
#' @author Muhammad Yaseen (\email{myaseen208@@gmail.com})
#' @seealso \code{\link{vlm_ems}}, \code{\link{vlm_fit}}, \code{\link{ex124}}
#' @family VetResearchLMM examples
#' @examples
#' # SAS program of the book (Appendix B):
#' #   proc glm data=ex124;
#' #     class herd dose drug;
#' #     model PCVdif = drug herd(drug) dose dose*drug;
#' #     random herd(drug) / test;
#' #   run;
#'
#' em <-
#'   vlm_ems(
#'       fixed  = PCVdif ~ drug + drug:herd + dose + dose:drug
#'     , data   = ex124
#'     , random = ~ drug:herd
#'     , type   = 3
#'     , class  = "herd"
#'     )
#' em
#'
#' # one observation deleted (Table 1.3.2.3)
#' em1 <-
#'   vlm_ems(
#'       fixed  = PCVdif ~ drug + drug:herd + dose + dose:drug
#'     , data   = ex124[-1, ]
#'     , random = ~ drug:herd
#'     , type   = 3
#'     , class  = "herd"
#'     )
#' em1$coefficients
#'
#' # the mixed model analysis that replaces it
#' fm <-
#'   vlm_fit(
#'       fixed    = PCVdif ~ drug + dose + drug:dose
#'     , data     = ex124
#'     , random   = ~ drug:herd
#'     , repeated = NULL
#'     , method   = "REML"
#'     , ddfm     = "satterth"
#'     , type     = 3
#'     , class    = "herd"
#'     , bound    = TRUE
#'     , control  = list()
#'     )
#' fm$tests
#' @name Examp1.3.2
NULL

#' Example 2.2.1.7: one-way analysis of variance, an estimate and a contrast
#'
#' @description
#' The three doses of \code{\link{ex121}} compared by the fixed effects model: F = 14.36 on 2 and 11 df, and the
#' low dose against the mean of the medium and high doses, -3.68 with standard error 0.937 (F = 15.44).
#'
#' @references
#' Duchateau, L., Janssen, P. and Rowlands, G. J. (1998). \emph{Linear Mixed Models. An Introduction with
#' Applications in Veterinary Research}. International Livestock Research Institute, Nairobi.
#' @author Muhammad Yaseen (\email{myaseen208@@gmail.com})
#' @seealso \code{\link{vlm_ems}}, \code{\link{vlm_estimate}}, \code{\link{ex121}}
#' @family VetResearchLMM examples
#' @examples
#' # SAS program of the book (Appendix B):
#' #   proc glm data=ex121;
#' #     class dose;
#' #     model PCVdif = dose;
#' #     estimate 'l vs mh' dose -0.5 1 -0.5;
#' #     contrast 'l vs mh' dose -0.5 1 -0.5;
#' #   run;
#'
#' em <-
#'   vlm_ems(
#'       fixed  = PCVdiff ~ dose
#'     , data   = ex121
#'     , random = NULL
#'     , type   = 3
#'     , class  = NULL
#'     )
#' em
#'
#' fm <-
#'   vlm_fit(
#'       fixed    = PCVdiff ~ dose
#'     , data     = ex121
#'     , random   = NULL
#'     , repeated = NULL
#'     , method   = "REML"
#'     , ddfm     = "default"
#'     , type     = 3
#'     , class    = NULL
#'     , bound    = TRUE
#'     , control  = list()
#'     )
#' # dose levels: H, L, M
#' vlm_estimate(
#'     fit    = fm
#'   , L      = list("l vs mh" = list(dose = c(-0.5, 1, -0.5)))
#'   , random = NULL
#'   , level  = 0.95
#'   )
#' vlm_contrast(
#'     fit = fm
#'   , L   = list("l vs mh" = list(dose = c(-0.5, 1, -0.5)))
#'   )
#' @name Examp2.2.1.7
NULL

#' Example 2.3.2: the mixed model descriptions of Chapter 2
#'
#' @description
#' The models of Section 2.3.2 for the examples of Chapter 1: a randomised block design with random herds
#' (\code{\link{ex122}}), herds nested in drug (\code{\link{ex123}}), two sizes of experimental units
#' (\code{\link{ex124}}) and the random effects model of the ELISA data (\code{\link{ex126}}), in which animals and
#' times are random and the overall mean is the only fixed effect. New in version 2.0.0.
#'
#' @references
#' Duchateau, L., Janssen, P. and Rowlands, G. J. (1998). \emph{Linear Mixed Models. An Introduction with
#' Applications in Veterinary Research}. International Livestock Research Institute, Nairobi.
#' @author Muhammad Yaseen (\email{myaseen208@@gmail.com})
#' @seealso \code{\link{vlm_fit}}, \code{\link{ex122}}, \code{\link{ex123}}, \code{\link{ex126}}
#' @family VetResearchLMM examples
#' @examples
#' # SAS program of the book (Appendix B):
#' #   proc mixed data=ex126;
#' #     class anim_id time;
#' #     model OD = ;
#' #     random anim_id time;
#' #   run;
#'
#' f122 <-
#'   vlm_fit(
#'       fixed    = PCVdif ~ dose
#'     , data     = ex122
#'     , random   = ~ herd
#'     , repeated = NULL
#'     , method   = "REML"
#'     , ddfm     = "default"
#'     , type     = 3
#'     , class    = NULL
#'     , bound    = TRUE
#'     , control  = list()
#'     )
#' f122$covariance
#' f123 <-
#'   vlm_fit(
#'       fixed    = PCVdif ~ drug
#'     , data     = ex123
#'     , random   = ~ drug:herd
#'     , repeated = NULL
#'     , method   = "REML"
#'     , ddfm     = "default"
#'     , type     = 3
#'     , class    = NULL
#'     , bound    = TRUE
#'     , control  = list()
#'     )
#' f123$tests
#' f126 <-
#'   vlm_fit(
#'       fixed    = OD ~ 1
#'     , data     = ex126
#'     , random   = ~ anim_id + time
#'     , repeated = NULL
#'     , method   = "REML"
#'     , ddfm     = "default"
#'     , type     = 3
#'     , class    = "time"
#'     , bound    = TRUE
#'     , control  = list()
#'     )
#' f126$covariance
#' vlm_interpret(
#'     x     = f126
#'   , alpha = 0.05
#'   , top   = 3
#'   )
#' @name Examp2.3.2
NULL

#' Example 2.4.2.2: ML and REML estimates of variance components
#'
#' @description
#' The split-plot data \code{\link{ex125}}: REML gives 5.151 (region), 0.387 (herd within region) and 2.096
#' (residual); ML gives the smaller 4.292, 0.322 and 1.747 (Table 2.4.2.1), because it ignores the degrees of
#' freedom used by the fixed effects. The Type 3 (moment) estimates equal REML here, as the data are balanced.
#'
#' @references
#' Duchateau, L., Janssen, P. and Rowlands, G. J. (1998). \emph{Linear Mixed Models. An Introduction with
#' Applications in Veterinary Research}. International Livestock Research Institute, Nairobi.
#' @author Muhammad Yaseen (\email{myaseen208@@gmail.com})
#' @seealso \code{\link{vlm_fit}}, \code{\link{ex125}}
#' @family VetResearchLMM examples
#' @examples
#' # SAS program of the book (Appendix B):
#' #   proc mixed data=ex125 method=ml;   * and method=reml;
#' #     class drug dose region;
#' #     model pcv = drug dose drug*dose;
#' #     random region drug*region;
#' #   run;
#'
#' ml <-
#'   vlm_fit(
#'       fixed    = Pcv ~ Drug + dose + Drug:dose
#'     , data     = ex125
#'     , random   = ~ Region + Region:Drug
#'     , repeated = NULL
#'     , method   = "ML"
#'     , ddfm     = "default"
#'     , type     = 3
#'     , class    = NULL
#'     , bound    = TRUE
#'     , control  = list()
#'     )
#' reml <-
#'   vlm_fit(
#'       fixed    = Pcv ~ Drug + dose + Drug:dose
#'     , data     = ex125
#'     , random   = ~ Region + Region:Drug
#'     , repeated = NULL
#'     , method   = "REML"
#'     , ddfm     = "default"
#'     , type     = 3
#'     , class    = NULL
#'     , bound    = TRUE
#'     , control  = list()
#'     )
#' mom <-
#'   vlm_fit(
#'       fixed    = Pcv ~ Drug + dose + Drug:dose
#'     , data     = ex125
#'     , random   = ~ Region + Region:Drug
#'     , repeated = NULL
#'     , method   = "Type3"
#'     , ddfm     = "default"
#'     , type     = 3
#'     , class    = NULL
#'     , bound    = TRUE
#'     , control  = list()
#'     )
#' cbind(ML = ml$covariance$estimate, REML = reml$covariance$estimate, Type3 = mom$covariance$estimate)
#'
#' # the same model with lme4 (optional)
#' if (requireNamespace("lme4", quietly = TRUE)) {
#'   lm4 <-
#'     lme4::lmer(
#'         formula = Pcv ~ Drug * dose + (1 | Region / Drug)
#'       , data    = ex125
#'       , REML    = TRUE
#'       )
#'   print(lme4::VarCorr(lm4), comp = "Variance")
#' }
#' @name Examp2.4.2.2
NULL

#' Example 2.4.3.1: best linear unbiased prediction of sire effects
#'
#' @description
#' The random sire model of \code{\link{ex127}}: REML variances 3.685 (sire) and 3.542 (residual), overall mean
#' 13.97, and the prediction 3.16 for sire 4, a shrunken version of its mean deviation 17.63 - 13.97.
#'
#' @references
#' Duchateau, L., Janssen, P. and Rowlands, G. J. (1998). \emph{Linear Mixed Models. An Introduction with
