#' #   proc mixed data=ex127;
#' #     class sire;
#' #     model ww = ;
#' #     random sire / solution;
#' #   run;
#'
#' fs <-
#'   vlm_fit(
#'       fixed    = Ww ~ 1
#'     , data     = ex127
