#' Example 2.5.3.1: confidence intervals with Satterthwaite degrees of freedom
#'
#' @description
#' Four linear combinations of the fixed effects of \code{\link{ex125}}: their variances 0.478, 1.0975, 0.698 and
#' 1.272 combine the variance components, and their Satterthwaite degrees of freedom (5, 6.2, 10 and 8.2) the
#' degrees of freedom of the mean squares of Table 2.5.3.1.
#'
#' @references
#' Duchateau, L., Janssen, P. and Rowlands, G. J. (1998). \emph{Linear Mixed Models. An Introduction with
#' Applications in Veterinary Research}. International Livestock Research Institute, Nairobi.
#' @author Muhammad Yaseen (\email{myaseen208@@gmail.com})
#' @seealso \code{\link{vlm_estimate}}, \code{\link{vlm_ems}}, \code{\link{ex125}}
#' @family VetResearchLMM examples
#' @examples
#' # SAS program of the book (Appendix B):
#' #   proc mixed data=ex125;
#' #     class drug dose region;
#' #     model pcv = drug dose drug*dose / ddfm=satterth;
#' #     random region drug*region;
#' #     estimate 'drug dif' drug -1 1 drug*dose -0.5 -0.5 0.5 0.5;
#' #     estimate 'Samorin mean' intercept 1 drug 0 1 dose 0.5 0.5 drug*dose 0 0 0.5 0.5;
#' #     estimate 'Samorin HvsL' dose 1 -1 drug*dose 0 0 1 -1;
#' #     estimate 'Samorin high' intercept 1 drug 0 1 dose 1 0 drug*dose 0 0 1 0;
#' #   run;
#'
#' fm <-
#'   vlm_fit(
#'       fixed    = Pcv ~ Drug + dose + Drug:dose
#'     , data     = ex125
#'     , random   = ~ Region + Region:Drug
#'     , repeated = NULL
#'     , method   = "REML"
#'     , ddfm     = "satterth"
#'     , type     = 3
#'     , class    = NULL
#'     , bound    = TRUE
#'     , control  = list()
#'     )
#' vlm_estimate(
#'     fit    = fm
#'   , L      = list(
#'           "drug dif"     = list(Drug = c(-1, 1), "Drug:dose" = c(-0.5, -0.5, 0.5, 0.5))
#'         , "Samorin mean" = list(Intercept = 1, Drug = c(0, 1),
#'                                 dose = c(0.5, 0.5), "Drug:dose" = c(0, 0, 0.5, 0.5))
#'         , "Samorin HvsL" = list(dose = c(1, -1), "Drug:dose" = c(0, 0, 1, -1))
#'         , "Samorin high" = list(Intercept = 1, Drug = c(0, 1),
#'                                 dose = c(1, 0), "Drug:dose" = c(0, 0, 1, 0))
#'         )
#'   , random = NULL
#'   , level  = 0.95
#'   )
#'
#' # the mean squares and their expectations (Table 2.5.3.1)
#' em <-
#'   vlm_ems(
#'       fixed  = Pcv ~ Region + Drug + Region:Drug + dose + Drug:dose
#'     , data   = ex125
#'     , random = ~ Region + Region:Drug
#'     , type   = 3
#'     , class  = NULL
#'     )
#' em
#' @name Examp2.5.3.1
NULL

#' Example 2.5.4.1: broad and narrow inference spaces
#'
#' @description
#' The mean of Samorin in \code{\link{ex125}}: its variance is 1.0975 when regions and herds are random (broad
#' space) and 0.175 for the six regions and herds of the study (narrow space), as in the fixed effects model.
#'
#' @details
#' The narrow-space estimate adds the random effects averaged over the observed levels (the part of an ESTIMATE
#' statement after the vertical bar in SAS); the fixed effects model with regions and herds fixed gives the same
#' standard error.
#'
#' @references
#' Duchateau, L., Janssen, P. and Rowlands, G. J. (1998). \emph{Linear Mixed Models. An Introduction with
#' Applications in Veterinary Research}. International Livestock Research Institute, Nairobi.
#' @author Muhammad Yaseen (\email{myaseen208@@gmail.com})
#' @seealso \code{\link{vlm_estimate}}, \code{\link{ex125}}
#' @family VetResearchLMM examples
#' @examples
#' # SAS program of the book (Appendix B):
#' #   proc mixed data=ex125;
#' #     class drug dose region;
#' #     model pcv = drug dose drug*dose / ddfm=satterth;
#' #     random region drug*region;
#' #     estimate 'Samorin mean' intercept 1 drug 0 1 dose 0.5 0.5 drug*dose 0 0 0.5 0.5;
#' #   run;
#' #   proc glm data=ex125;
#' #     class drug dose region;
#' #     model pcv = region drug drug*region dose drug*dose;
#' #     estimate 'Samorin mean' intercept 1 drug 0 1 dose 0.5 0.5 drug*dose 0 0 0.5 0.5;
#' #   run;
#'
#' fm <-
#'   vlm_fit(
#'       fixed    = Pcv ~ Drug + dose + Drug:dose
#'     , data     = ex125
#'     , random   = ~ Region + Region:Drug
#'     , repeated = NULL
#'     , method   = "REML"
#'     , ddfm     = "satterth"
#'     , type     = 3
#'     , class    = NULL
#'     , bound    = TRUE
#'     , control  = list()
#'     )
#' vlm_estimate(
#'     fit    = fm
#'   , L      = list(
#'           "broad"  = list(Intercept = 1, Drug = c(0, 1),
#'                           dose = c(0.5, 0.5), "Drug:dose" = c(0, 0, 0.5, 0.5))
#'         , "narrow" = list(Intercept = 1, Drug = c(0, 1),
#'                           dose = c(0.5, 0.5), "Drug:dose" = c(0, 0, 0.5, 0.5))
#'         )
#'   , random = list(
#'           "narrow" = list(Region = rep(1 / 6, 6), "Region:Drug" = rep(c(0, 1 / 6), 6))
#'         )
#'   , level  = 0.95
#'   )
#'
#' # the fixed effects model: regions and herds fixed
#' ff <-
#'   vlm_fit(
#'       fixed    = Pcv ~ Region + Drug + Region:Drug + dose + Drug:dose
#'     , data     = ex125
#'     , random   = NULL
#'     , repeated = NULL
#'     , method   = "REML"
#'     , ddfm     = "default"
#'     , type     = 3
#'     , class    = "Region"
#'     , bound    = TRUE
#'     , control  = list()
#'     )
#' vlm_estimate(
#'     fit    = ff
#'   , L      = list(
#'           "Samorin mean" = list(Intercept = 1, Region = rep(1 / 6, 6), Drug = c(0, 1),
#'                                 "Region:Drug" = rep(c(0, 1 / 6), 6), dose = c(0.5, 0.5),
#'                                 "Drug:dose" = c(0, 0, 0.5, 0.5))
#'         )
#'   , random = NULL
#'   , level  = 0.95
#'   )
#' @name Examp2.5.4.1
NULL

#' Example 2.6.1: F tests of general linear hypotheses
#'
#' @description
#' The drug difference of \code{\link{ex125}} (estimate -5.56, variance 0.478, F on 1 and 5 df) and the joint test
#' that the four cell means are equal: F = 31.2 on 3 and 7.14 df, p = 0.0002.
#'
#' @references
#' Duchateau, L., Janssen, P. and Rowlands, G. J. (1998). \emph{Linear Mixed Models. An Introduction with
#' Applications in Veterinary Research}. International Livestock Research Institute, Nairobi.
#' @author Muhammad Yaseen (\email{myaseen208@@gmail.com})
#' @seealso \code{\link{vlm_contrast}}, \code{\link{ex125}}
#' @family VetResearchLMM examples
#' @examples
#' # SAS program of the book (Appendix B):
#' #   proc mixed data=ex125;
#' #     class drug dose region;
#' #     model pcv = drug dose drug*dose / ddfm=satterth;
#' #     random region drug*region;
#' #     contrast 'drug dif' drug -1 1 drug*dose -0.5 -0.5 0.5 0.5;
#' #     contrast 'all' drug 1 -1 dose 0 0 drug*dose 0.5 0.5 -0.5 -0.5,
#' #                    drug 0 0 dose 1 -1 drug*dose 0.5 -0.5 0.5 -0.5,
#' #                    drug 0 0 dose 0 0 drug*dose 0.5 -0.5 -0.5 0.5;
#' #   run;
#'
#' fm <-
#'   vlm_fit(
#'       fixed    = Pcv ~ Drug + dose + Drug:dose
#'     , data     = ex125
#'     , random   = ~ Region + Region:Drug
#'     , repeated = NULL
#'     , method   = "REML"
#'     , ddfm     = "satterth"
#'     , type     = 3
#'     , class    = NULL
#'     , bound    = TRUE
#'     , control  = list()
#'     )
#' vlm_contrast(
#'     fit = fm
#'   , L   = list(
#'           "drug dif" = list(Drug = c(-1, 1), "Drug:dose" = c(-0.5, -0.5, 0.5, 0.5))
#'         , "all"      = list(
#'               list(Drug = c(1, -1), "Drug:dose" = c(0.5, 0.5, -0.5, -0.5))
#'             , list(dose = c(1, -1), "Drug:dose" = c(0.5, -0.5, 0.5, -0.5))
#'             , list("Drug:dose" = c(0.5, -0.5, -0.5, 0.5))
#'             )
#'         )
#'   )
#' @name Examp2.6.1
NULL

#' Example 3.1: a designed experiment with doses nested in drug and a covariate
#'
#' @description
#' Berenil at two doses and Samorin at one dose, given to animals in herds nested in drug (\code{\link{ex31}}).
#' Model 1 compares the three treatments; Model 2 adds the PCV at treatment as a covariate with a common slope;
#' Model 3 allows a slope per treatment and compares the treatments at PCV1 = 18. The book prints only part of the
#' data, so the numbers differ from those of the book.
#'
#' @references
#' Duchateau, L., Janssen, P. and Rowlands, G. J. (1998). \emph{Linear Mixed Models. An Introduction with
#' Applications in Veterinary Research}. International Livestock Research Institute, Nairobi.
#' @author Muhammad Yaseen (\email{myaseen208@@gmail.com})
#' @seealso \code{\link{vlm_fit}}, \code{\link{vlm_lsmeans}}, \code{\link{ex31}}
#' @family VetResearchLMM examples
#' @examples
#' # SAS program of the book (Appendix B):
#' #   proc mixed data=ex31;
#' #     class drug dose herd;
#' #     model PCV2 = drug dose(drug) / solution ddfm=satterth;
#' #     random herd(drug);
#' #     estimate 'Mean Samorin' intercept 1 drug 0 1 dose(drug) 0 0 1;
#' #     estimate 'Berenil 2 doses' dose(drug) 1 -1 0;
#' #     estimate 'Ber vs Sam at dose 1' drug 1 -1 dose(drug) 1 0 -1;
#' #     contrast 'some difference' drug 1 -1 dose(drug) 0.5 0.5 -1, drug 0 0 dose(drug) 1 -1 0;
#' #     lsmeans dose(drug);
#' #   run;
#' #   * Model 3: model PCV2 = drug dose(drug) PCV1*dose(drug); lsmeans dose(drug) / at PCV1=18;
#'
#' m1 <-
#'   vlm_fit(
#'       fixed    = PCV2 ~ drug + drug:dose
#'     , data     = ex31
#'     , random   = ~ drug:herd
#'     , repeated = NULL
#'     , method   = "REML"
#'     , ddfm     = "satterth"
#'     , type     = 3
#'     , class    = c("herd", "dose")
#'     , bound    = TRUE
#'     , control  = list()
#'     )
#' m1$tests
#' vlm_estimate(
#'     fit    = m1
#'   , L      = list(
#'           "Mean Samorin"         = list(Intercept = 1, drug = c(0, 1), "drug:dose" = c(0, 0, 1))
#'         , "Berenil 2 doses"      = list("drug:dose" = c(1, -1, 0))
#'         , "Ber vs Sam at dose 1" = list(drug = c(1, -1), "drug:dose" = c(1, 0, -1))
#'         )
#'   , random = NULL
#'   , level  = 0.95
#'   )
#' vlm_contrast(
#'     fit = m1
#'   , L   = list(
#'           "some difference" = list(
#'               list(drug = c(1, -1), "drug:dose" = c(0.5, 0.5, -1))
#'             , list("drug:dose" = c(1, -1, 0))
#'             )
#'         )
#'   )
#' vlm_lsmeans(
#'     fit    = m1
#'   , specs  = ~ drug:dose
#'   , at     = NULL
#'   , diff   = FALSE
#'   , adjust = "none"
#'   , level  = 0.95
#'   )
#' m2 <-
#'   vlm_fit(
#'       fixed    = PCV2 ~ PCV1 + drug + drug:dose
#'     , data     = ex31
#'     , random   = ~ drug:herd
#'     , repeated = NULL
#'     , method   = "REML"
#'     , ddfm     = "satterth"
#'     , type     = 3
#'     , class    = c("herd", "dose")
#'     , bound    = TRUE
#'     , control  = list()
#'     )
#' m2$fixed
#' m3 <-
#'   vlm_fit(
#'       fixed    = PCV2 ~ drug + drug:dose + PCV1:drug:dose
#'     , data     = ex31
#'     , random   = ~ drug:herd
#'     , repeated = NULL
#'     , method   = "REML"
#'     , ddfm     = "satterth"
#'     , type     = 3
#'     , class    = c("herd", "dose")
#'     , bound    = TRUE
#'     , control  = list()
#'     )
#' vlm_lsmeans(
#'     fit    = m3
#'   , specs  = ~ drug:dose
#'   , at     = list(PCV1 = 18)
#'   , diff   = FALSE
#'   , adjust = "none"
#'   , level  = 0.95
#'   )
#' @name Examp3.1
