#' Example 3.2: sires nested in breed, heritability and breed comparisons
#'
#' @description
#' Weaning weights of lambs (\code{\link{ex32}}) with sex, age and breed fixed and sires within breed random: the
#' heritability \eqn{h^2 = 4\sigma_s^2/(\sigma_s^2 + \sigma^2)}, Tukey-Kramer comparisons of the breeds and the
#' predicted breeding values of the sires. The book prints only part of the data, so the numbers differ from those
#' of the book (for this part the sire variance is estimated as zero).
#'
#' @references
#' Duchateau, L., Janssen, P. and Rowlands, G. J. (1998). \emph{Linear Mixed Models. An Introduction with
#' Applications in Veterinary Research}. International Livestock Research Institute, Nairobi.
#' @author Muhammad Yaseen (\email{myaseen208@@gmail.com})
#' @seealso \code{\link{vlm_lsmeans}}, \code{\link{vlm_blup}}, \code{\link{ex32}}
#' @family VetResearchLMM examples
#' @examples
#' # SAS program of the book (Appendix B):
#' #   proc mixed data=ex32;
#' #     class sex sire_id breed;
#' #     model ww = sex agew breed / solution ddfm=satterth;
#' #     random sire_id(breed) / solution;
#' #     lsmeans breed / adjust=tukey;
#' #   run;
#'
#' fm <-
#'   vlm_fit(
#'       fixed    = Ww ~ sex + agew + breed
#'     , data     = ex32
#'     , random   = ~ breed:sire_id
#'     , repeated = NULL
#'     , method   = "REML"
#'     , ddfm     = "satterth"
#'     , type     = 3
#'     , class    = "breed"
#'     , bound    = TRUE
#'     , control  = list()
#'     )
#' v <- fm$covariance$estimate
#' h2 <- 4 * v[1] / sum(v)
#' h2
#' vlm_lsmeans(
#'     fit    = fm
#'   , specs  = ~ breed
#'   , at     = NULL
#'   , diff   = TRUE
#'   , adjust = "tukey"
#'   , level  = 0.95
#'   )
#' vlm_blup(
#'     fit   = fm
#'   , level = 0.95
#'   )
#' @name Examp3.2
NULL

#' Example 3.3: covariance structures for repeated measures
#'
#' @description
#' PCV of 12 animals of two breeds measured 14 times (\code{\link{ex33}}). Model 1 has a random animal effect,
#' equivalent to compound symmetry (variances 5.478 and 4.965; -2 restricted log-likelihood 783.451); Model 2 has
#' first-order autoregressive errors (rho = 0.621, residual 10.191; 793.139); Model 3 has a random intercept and
#' slope per animal with an unstructured covariance (12.46, -0.2551, 0.005758 and residual 4.353).
#'
#' @references
#' Duchateau, L., Janssen, P. and Rowlands, G. J. (1998). \emph{Linear Mixed Models. An Introduction with
#' Applications in Veterinary Research}. International Livestock Research Institute, Nairobi.
#' @author Muhammad Yaseen (\email{myaseen208@@gmail.com})
#' @seealso \code{\link{vlm_random}}, \code{\link{vlm_repeated}}, \code{\link{vlm_compare}}, \code{\link{ex33}}
#' @family VetResearchLMM examples
#' @examples
#' # SAS program of the book (Appendix B):
#' #   proc mixed data=ex33; class breed anim_id; model pcv = breed breed*time / solution;
#' #     random anim_id(breed) / solution;                               * Model 1;
#' #     repeated / type=cs sub=anim_id(breed) r;                         * Model 1, second form;
#' #     repeated / type=ar(1) sub=anim_id(breed) r;                      * Model 2;
#' #     random intercept time / type=un sub=anim_id(breed) solution;     * Model 3;
#' #   run;
#'
#' m1 <-
#'   vlm_fit(
#'       fixed    = PCV ~ breed + breed:time
#'     , data     = ex33
#'     , random   = ~ animal_id:breed
#'     , repeated = NULL
#'     , method   = "REML"
#'     , ddfm     = "default"
#'     , type     = 3
#'     , class    = NULL
#'     , bound    = TRUE
#'     , control  = list()
#'     )
#' m1$fixed
#' vlm_blup(
#'     fit   = m1
#'   , level = 0.95
#'   )
#' cs <-
#'   vlm_fit(
#'       fixed    = PCV ~ breed + breed:time
#'     , data     = ex33
#'     , random   = NULL
#'     , repeated = vlm_repeated(
#'           type    = c("vc", "cs", "ar1", "sp_pow", "un")[2]
#'         , subject = ~ animal_id:breed
#'         , order   = NULL
#'         )
#'     , method   = "REML"
#'     , ddfm     = "default"
#'     , type     = 3
#'     , class    = NULL
#'     , bound    = TRUE
#'     , control  = list()
#'     )
#' cs$fit
#' m1c <-
#'   vlm_fit(
#'       fixed    = PCV ~ time + breed + breed:time
#'     , data     = ex33
#'     , random   = ~ animal_id:breed
#'     , repeated = NULL
#'     , method   = "REML"
#'     , ddfm     = "default"
#'     , type     = 3
#'     , class    = NULL
#'     , bound    = TRUE
#'     , control  = list()
#'     )
#' m1c$tests
#' ar <-
#'   vlm_fit(
#'       fixed    = PCV ~ breed + breed:time
#'     , data     = ex33
#'     , random   = NULL
#'     , repeated = vlm_repeated(
#'           type    = c("vc", "cs", "ar1", "sp_pow", "un")[3]
#'         , subject = ~ animal_id:breed
#'         , order   = ~ time
#'         )
#'     , method   = "REML"
#'     , ddfm     = "default"
#'     , type     = 3
#'     , class    = NULL
#'     , bound    = TRUE
#'     , control  = list()
#'     )
#' ar$covariance
#' rc <-
#'   vlm_fit(
#'       fixed    = PCV ~ breed + breed:time
#'     , data     = ex33
#'     , random   = vlm_random(
#'           effects = ~ 1 + time
#'         , subject = ~ animal_id:breed
#'         , type    = c("vc", "un")[2]
#'         )
#'     , repeated = NULL
#'     , method   = "REML"
#'     , ddfm     = "default"
#'     , type     = 3
#'     , class    = NULL
#'     , bound    = TRUE
#'     , control  = list()
#'     )
#' rc$covariance
#' vlm_compare(
#'     CS   = cs
#'   , AR1  = ar
#'   , RC   = rc
#'   , test = TRUE
#'   )
#'
#' # the same model with lme4 (optional)
#' if (requireNamespace("lme4", quietly = TRUE)) {
#'   lm4 <-
#'     lme4::lmer(
#'         formula = PCV ~ breed + breed:time + (1 | animal_id)
#'       , data    = ex33
#'       , REML    = TRUE
#'       )
#'   print(lme4::VarCorr(lm4), comp = "Variance")
#' }
#' @name Examp3.3
NULL
